################################################################################
## Form generated by hand to match the Designer-output pattern (no .ui file).
##
## Excel 合并 Tab 的纯布局代码 —— 与 invoice 的 generated/ui_invoice_dialog.py
## 风格一致:一个 Ui_* 类,setupUi(self, Widget) 构建控件树。
## 业务逻辑(信号连接/合并/结果展示)留在 dialogs/excel_merge_tab.py 的 ExcelMergeTab。
##
## WARNING! 若日后用 Qt Designer 重新生成,本文件会被覆盖。
##
## 本文件在 scripts/regen_ui.py 的 HANDMADE 清单中(无 .ui、不走 pyside6-uic 再生)。
################################################################################

from PySide6.QtWidgets import (
    QCheckBox,
    QComboBox,
    QHBoxLayout,
    QHeaderView,
    QLabel,
    QLineEdit,
    QListWidget,
    QPushButton,
    QTableWidget,
    QVBoxLayout,
    QWidget,
)

# 结果表格列头(与合并结果字段一一对应;放此处供 setupUi 与测试共用)
HEADERS = ["文件", "工作表", "合并后名称", "状态"]

# 选项下拉框文案(索引 -> 常量值的映射见 controllers/excel_merge_controller.py)
NAMING_LABELS = ["文件名-工作表名", "保留原名(冲突自动加序号)"]
MODE_LABELS = ["值(公式取计算结果)", "公式原文"]


class Ui_ExcelMergeDialog:
    """Excel 合并 Tab 的 UI 构建器(setupUi 模式,与其他 Tab 一致)。"""

    def setupUi(self, ExcelMergeDialog: QWidget) -> None:
        if not ExcelMergeDialog.objectName():
            ExcelMergeDialog.setObjectName("ExcelMergeDialog")

        layout = QVBoxLayout(ExcelMergeDialog)
        layout.setObjectName("verticalLayout_main")

        # ---- 文件选择行 ----
        file_row = QHBoxLayout()
        file_row.setObjectName("horizontalLayout_files")

        self.btn_add_files = QPushButton("添加文件", ExcelMergeDialog)
        self.btn_add_files.setObjectName("btn_add_files")
        file_row.addWidget(self.btn_add_files)

        self.btn_add_folder = QPushButton("添加文件夹", ExcelMergeDialog)
        self.btn_add_folder.setObjectName("btn_add_folder")
        file_row.addWidget(self.btn_add_folder)

        self.btn_clear = QPushButton("清空", ExcelMergeDialog)
        self.btn_clear.setObjectName("btn_clear")
        file_row.addWidget(self.btn_clear)

        file_row.addStretch(1)
        layout.addLayout(file_row)

        self.list_files = QListWidget(ExcelMergeDialog)
        self.list_files.setObjectName("list_files")
        layout.addWidget(self.list_files)

        # ---- 选项行(命名 / 内容模式 / 隐藏工作表) ----
        opt_row = QHBoxLayout()
        opt_row.setObjectName("horizontalLayout_options")

        opt_row.addWidget(QLabel("工作表命名:", ExcelMergeDialog))

        self.cmb_naming = QComboBox(ExcelMergeDialog)
        self.cmb_naming.setObjectName("cmb_naming")
        self.cmb_naming.addItems(NAMING_LABELS)
        self.cmb_naming.setCurrentIndex(0)
        opt_row.addWidget(self.cmb_naming)

        opt_row.addWidget(QLabel("内容:", ExcelMergeDialog))

        self.cmb_mode = QComboBox(ExcelMergeDialog)
        self.cmb_mode.setObjectName("cmb_mode")
        self.cmb_mode.addItems(MODE_LABELS)
        self.cmb_mode.setCurrentIndex(0)
        opt_row.addWidget(self.cmb_mode)

        self.chk_hidden = QCheckBox("包含隐藏工作表", ExcelMergeDialog)
        self.chk_hidden.setObjectName("chk_hidden")
        opt_row.addWidget(self.chk_hidden)

        opt_row.addStretch(1)
        layout.addLayout(opt_row)

        # ---- 输出目录行 ----
        out_row = QHBoxLayout()
        out_row.setObjectName("horizontalLayout_output")

        out_row.addWidget(QLabel("输出目录:", ExcelMergeDialog))

        self.edit_outdir = QLineEdit(ExcelMergeDialog)
        self.edit_outdir.setObjectName("edit_outdir")
        self.edit_outdir.setPlaceholderText("选择或输入输出目录(默认跟随上次或首个源文件目录)")
        out_row.addWidget(self.edit_outdir)

        self.btn_browse = QPushButton("浏览", ExcelMergeDialog)
        self.btn_browse.setObjectName("btn_browse")
        out_row.addWidget(self.btn_browse)

        layout.addLayout(out_row)

        # ---- 操作按钮行 ----
        btn_row = QHBoxLayout()
        btn_row.setObjectName("horizontalLayout_buttons")

        self.btn_merge = QPushButton("开始合并", ExcelMergeDialog)
        self.btn_merge.setObjectName("btn_merge")
        btn_row.addWidget(self.btn_merge)

        btn_row.addStretch(1)

        self.lbl_status = QLabel("就绪", ExcelMergeDialog)
        self.lbl_status.setObjectName("lbl_status")
        btn_row.addWidget(self.lbl_status)

        layout.addLayout(btn_row)

        # ---- 结果表格 ----
        self.table = QTableWidget(0, len(HEADERS), ExcelMergeDialog)
        self.table.setObjectName("table")
        self.table.setHorizontalHeaderLabels(HEADERS)
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch)
        layout.addWidget(self.table, stretch=1)
